{"path": "compute.cpp", "content": "// compute.cpp: compute kernel for transc_log_wide (log per element)
#include "tt_metal/tt_metal.hpp"
using namespace tt::tt_metal;

void kernel_main() {
    // Runtime args: [num_tiles]
    const uint32_t num_tiles = get_arg_val<uint32_t>(0);

    constexpr uint32_t cb_in = tt::CB::c_in0;   // CB 0
    constexpr uint32_t cb_out = tt::CB::c_out0; // CB 16 (output)

    // Each tile has 32*32 = 1024 float32 elements
    constexpr uint32_t TILE_ELEMS = 32 * 32;

    for (uint32_t t = 0; t < num_tiles; ++t) {
        // Wait for an input tile to be available
        cb_wait_front(cb_in, 1);
        // Reserve space for one output tile
        cb_reserve_back(cb_out, 1);

        // Get pointers to the tile data in L1 memory
        uint32_t l1_read_addr = get_read_ptr(cb_in);
        uint32_t l1_write_addr = get_write_ptr(cb_out);

        // Compute log element‑wise
        // Using float32 logf from <cmath>
        for (uint32_t i = 0; i < TILE_ELEMS; ++i) {
            ((float*)l1_write_addr)[i] = logf(((float*)l1_read_addr)[i]);
        }

        // Commit the output tile and release the input tile
        cb_push_back(cb_out, 1);
        cb_pop_front(cb_in, 1);
    }
}
"}

